:root {
  --ink: #172126;
  --paper: #eef2ed;
  --panel: #fffdf9;
  --panel-strong: #edf3ef;
  --line: #c9d4ce;
  --muted: #64706b;
  --teal: #0f766e;
  --blue: #2457a6;
  --rose: #b56576;
  --amber: #f2b84b;
  --green: #77a06a;
  --shadow: 0 18px 42px rgba(23, 33, 38, 0.14);
  color: var(--ink);
  background: var(--paper);
  font-family: "Avenir Next", "Hiragino Sans", "Yu Gothic", "Meiryo", sans-serif;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
}

* {
  box-sizing: border-box;
}

html {
  min-width: 320px;
  background: var(--paper);
}

body {
  margin: 0;
  min-width: 320px;
  min-height: 100vh;
}

button,
input,
textarea {
  font: inherit;
}

button,
a {
  -webkit-tap-highlight-color: transparent;
}

button {
  border: 0;
  cursor: pointer;
}

button:disabled {
  cursor: wait;
  opacity: 0.68;
}

.app-shell {
  width: min(1800px, calc(100vw - 28px));
  margin: 0 auto;
  padding: 14px 0 34px;
}

.deferred-panel {
  min-width: 0;
  display: block;
  content-visibility: auto;
  contain-intrinsic-size: 520px;
}

.deferred-panel.is-loaded {
  min-height: 0 !important;
  contain-intrinsic-size: auto;
}

.deferred-panel-placeholder {
  min-height: inherit;
  border: 1px solid rgba(23, 33, 38, 0.1);
  border-radius: 8px;
  background:
    linear-gradient(90deg, rgba(255, 253, 249, 0.72), rgba(237, 243, 239, 0.92), rgba(255, 253, 249, 0.72)),
    var(--panel);
  background-size: 240% 100%;
  animation: deferred-shimmer 1.4s ease-in-out infinite;
}

@keyframes deferred-shimmer {
  from {
    background-position: 120% 0;
  }

  to {
    background-position: -120% 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  .deferred-panel-placeholder {
    animation: none;
  }
}

.market-sky {
  min-height: clamp(560px, calc(100svh - 76px), 680px);
  display: grid;
  grid-template-columns: minmax(340px, 0.46fr) minmax(430px, 0.54fr);
  align-items: center;
  gap: 22px;
  padding: 28px;
  border: 1px solid #2b332d;
  border-radius: 8px;
  color: #fffdf7;
  background-color: #101318;
  background-image:
    linear-gradient(90deg, rgba(10, 19, 24, 0.9), rgba(10, 19, 24, 0.44)),
    url("/assets/agent-marketplace-hero.png");
  background-image:
    linear-gradient(90deg, rgba(10, 19, 24, 0.9), rgba(10, 19, 24, 0.44)),
    image-set(
      url("/assets/agent-marketplace-hero.webp") type("image/webp"),
      url("/assets/agent-marketplace-hero.png") type("image/png")
    );
  background-position: center, center;
  background-size: auto, cover;
  background-repeat: no-repeat, no-repeat;
  box-shadow: var(--shadow);
  overflow: hidden;
}

.market-identity {
  max-width: 820px;
  align-self: start;
  display: grid;
  align-content: center;
  justify-items: start;
  gap: 13px;
  padding-top: clamp(112px, 18svh, 170px);
}

.event-pill,
.chip,
.toolbar-badges span,
.agent-metrics span,
.skill-row span,
.matched-terms span,
.rarity,
.icon-link {
  min-height: 28px;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  border-radius: 999px;
  border: 1px solid rgba(23, 33, 38, 0.16);
  padding: 5px 10px;
  font-size: 0.78rem;
  font-weight: 800;
  line-height: 1.1;
  white-space: nowrap;
}

.event-pill {
  color: #14221f;
  background: rgba(255, 253, 247, 0.92);
}

h1,
h2,
h3,
p {
  margin: 0;
}

h1 {
  margin-top: 16px;
  max-width: 780px;
  font-family: "Avenir Next Condensed", "Hiragino Sans", sans-serif;
  font-size: 4.05rem;
  line-height: 0.92;
  letter-spacing: 0;
}

.market-identity h1 {
  margin-top: 0;
}

.market-identity p {
  width: min(720px, 100%);
  margin-top: 0;
  color: rgba(255, 253, 247, 0.86);
  font-size: 1.05rem;
  line-height: 1.55;
}

.market-hero-actions {
  width: min(720px, 100%);
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 0;
}

.market-hero-first-output-rail {
  width: min(720px, 100%);
  display: grid;
  grid-template-columns: minmax(118px, 0.55fr) repeat(3, minmax(0, 1fr));
  gap: 7px;
  padding: 7px;
  border: 1px solid rgba(255, 253, 247, 0.2);
  border-left: 5px solid #83b6d9;
  border-radius: 8px;
  color: #fffdf7;
  background:
    linear-gradient(135deg, rgba(131, 182, 217, 0.16), rgba(184, 239, 212, 0.07)),
    rgba(10, 19, 24, 0.5);
  box-shadow: inset 0 1px 0 rgba(255, 253, 247, 0.12);
  backdrop-filter: blur(12px);
}

.market-hero-first-output-copy,
.market-hero-first-output-rail a {
  min-width: 0;
  display: grid;
  align-content: center;
  gap: 5px;
}

.market-hero-first-output-copy {
  padding: 7px 8px;
}

.market-hero-unlock-brief {
  grid-column: 2 / -1;
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(128px, 0.42fr);
  gap: 8px;
  align-items: stretch;
  padding: 9px;
  border: 1px solid rgba(255, 253, 247, 0.2);
  border-left: 4px solid #b8efd4;
  border-radius: 8px;
  background:
    linear-gradient(135deg, rgba(184, 239, 212, 0.16), rgba(242, 215, 140, 0.08)),
    rgba(255, 253, 247, 0.08);
}

.market-hero-unlock-brief.is-hold {
  border-left-color: #ff9aa8;
}

.market-hero-unlock-brief.is-review {
  border-left-color: #f2d78c;
}

.market-hero-unlock-copy {
  min-width: 0;
  display: grid;
  gap: 5px;
}

.market-hero-unlock-copy span,
.market-hero-unlock-metrics span,
.market-hero-unlock-action span {
  color: rgba(184, 239, 212, 0.88);
  font-size: 0.64rem;
  font-weight: 950;
  line-height: 1.1;
  text-transform: uppercase;
}

.market-hero-unlock-copy strong {
  color: #fffdf7;
  font-size: 0.92rem;
  line-height: 1.12;
  overflow-wrap: anywhere;
}

.market-hero-unlock-copy small {
  display: -webkit-box;
  overflow: hidden;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  color: rgba(255, 253, 247, 0.72);
  font-size: 0.68rem;
  line-height: 1.25;
  overflow-wrap: anywhere;
}

.market-hero-unlock-metrics {
  grid-column: 1 / -1;
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.market-hero-unlock-metrics span {
  min-height: 22px;
  display: inline-flex;
  align-items: center;
  border: 1px solid rgba(255, 253, 247, 0.14);
  border-radius: 999px;
  padding: 4px 7px;
  color: rgba(255, 253, 247, 0.8);
  background: rgba(10, 19, 24, 0.32);
  text-transform: none;
  overflow-wrap: anywhere;
}

.market-hero-first-output-rail .market-hero-unlock-action {
  min-height: 0;
  display: grid;
  align-content: center;
  gap: 5px;
  padding: 8px;
  border: 1px solid rgba(184, 239, 212, 0.26);
  border-radius: 8px;
  color: inherit;
  background: rgba(10, 19, 24, 0.28);
  text-decoration: none;
}

.market-hero-unlock-action strong {
  color: #fffdf7;
  font-size: 0.78rem;
  line-height: 1.12;
  overflow-wrap: anywhere;
}

.market-hero-unlock-action small {
  display: -webkit-box;
  overflow: hidden;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  color: rgba(255, 253, 247, 0.68);
  font-size: 0.64rem;
  line-height: 1.2;
}

.market-hero-buyer-decision-snapshot {
  display: none;
}

.market-hero-first-output-copy span,
.market-hero-first-output-rail a span {
  color: rgba(184, 239, 212, 0.86);
  font-size: 0.66rem;
  font-weight: 950;
  line-height: 1.1;
  text-transform: uppercase;
}

.market-hero-first-output-copy strong {
  color: #fffdf7;
  font-size: 0.9rem;
  line-height: 1.1;
  overflow-wrap: anywhere;
}

.market-hero-first-output-rail a {
  min-height: 78px;
  padding: 8px;
  border: 1px solid rgba(255, 253, 247, 0.16);
  border-left: 4px solid rgba(131, 182, 217, 0.82);
  border-radius: 8px;
  color: inherit;
  background: rgba(255, 253, 247, 0.08);
  text-decoration: none;
}

.market-hero-first-output-rail a:nth-of-type(2) {
  border-left-color: rgba(184, 239, 212, 0.78);
}

.market-hero-first-output-rail a:nth-of-type(3) {
  border-left-color: rgba(242, 215, 140, 0.82);
}

.market-hero-first-output-rail a svg {
  color: #b8efd4;
}

.market-hero-first-output-rail a strong {
  color: #fffdf7;
  font-size: 0.76rem;
  line-height: 1.12;
  overflow-wrap: anywhere;
}

.market-hero-first-output-rail a small {
  display: -webkit-box;
  overflow: hidden;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  color: rgba(255, 253, 247, 0.68);
  font-size: 0.66rem;
  line-height: 1.2;
  overflow-wrap: anywhere;
}

.market-hero-first-output-rail a em {
  width: fit-content;
  min-height: 24px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(255, 253, 247, 0.18);
  border-radius: 999px;
  padding: 4px 7px;
  color: rgba(255, 253, 247, 0.82);
  background: rgba(255, 253, 247, 0.08);
  font-size: 0.63rem;
  font-style: normal;
  font-weight: 950;
  line-height: 1.1;
  text-transform: uppercase;
  white-space: nowrap;
}

.market-hero-first-output-status.is-send,
.market-hero-first-output-status.is-ready,
.market-hero-first-output-meter.is-ready {
  color: #102226;
  border-color: rgba(184, 239, 212, 0.76);
  background: #b8efd4;
}

.market-hero-first-output-status.is-review,
.market-hero-first-output-status.is-attention,
.market-hero-first-output-meter.is-attention {
  color: #1f2418;
  border-color: rgba(242, 215, 140, 0.78);
  background: #f2d78c;
}

.market-hero-first-output-status.is-hold,
.market-hero-first-output-status.is-blocked,
.market-hero-first-output-meter.is-blocked {
  color: #fffdf7;
  border-color: rgba(246, 193, 199, 0.62);
  background: rgba(181, 101, 118, 0.42);
}

.market-hero-first-output-rail a:hover,
.market-hero-first-output-rail a:focus-visible {
  outline: 2px solid rgba(255, 253, 247, 0.86);
  outline-offset: 3px;
}

@media (max-width: 860px) {
  .market-identity {
    padding-top: 0;
  }

  .market-hero-first-output-rail {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .market-hero-first-output-copy {
    grid-column: 1 / -1;
  }

  .market-hero-unlock-brief {
    grid-column: 1 / -1;
    grid-template-columns: 1fr;
  }

  .market-hero-first-output-rail .market-hero-unlock-action {
    min-height: 58px;
  }

}

.hero-workflow-intake-console {
  width: min(780px, 100%);
  display: grid;
  gap: 9px;
  padding: 11px;
  border: 1px solid rgba(255, 253, 247, 0.24);
  border-left: 5px solid #83b6d9;
  border-radius: 8px;
  color: #fffdf7;
  background:
    linear-gradient(135deg, rgba(131, 182, 217, 0.18), rgba(184, 239, 212, 0.08)),
    rgba(10, 19, 24, 0.72);
  box-shadow: inset 0 1px 0 rgba(255, 253, 247, 0.12);
  backdrop-filter: blur(14px);
}

.market-sky > .hero-workflow-intake-console {
  align-self: start;
  margin-top: 14px;
}

.homepage-buyer-board-memo {
  margin: 14px 0;
  display: grid;
  grid-template-columns: minmax(0, 1.08fr) minmax(160px, 0.22fr);
  gap: 12px;
  padding: 16px;
  border: 1px solid #2b332d;
  border-radius: 8px;
  color: #fffdf7;
  background:
    linear-gradient(135deg, rgba(13, 25, 28, 0.98), rgba(30, 44, 39, 0.94)),
    #101318;
  box-shadow: var(--shadow);
}

.homepage-buyer-board-memo.is-ready {
  border-left: 5px solid #77a06a;
}

.homepage-buyer-board-memo.is-attention {
  border-left: 5px solid #f2b84b;
}

.homepage-buyer-board-memo.is-blocked {
  border-left: 5px solid #b56576;
}

.homepage-buyer-board-memo-main {
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 14px;
  align-items: end;
}

.homepage-buyer-board-memo-copy {
  min-width: 0;
  display: grid;
  gap: 7px;
}

.homepage-buyer-board-memo-copy span,
.homepage-buyer-board-memo-verdict span,
.homepage-buyer-board-memo-metrics span,
.homepage-buyer-board-memo-questions span {
  color: rgba(184, 239, 212, 0.86);
  font-size: 0.68rem;
  font-weight: 950;
  line-height: 1.1;
  text-transform: uppercase;
}

.homepage-buyer-board-memo-copy h2 {
  max-width: 920px;
  color: #fffdf7;
  font-size: clamp(1.65rem, 3vw, 2.7rem);
  line-height: 1.02;
  letter-spacing: 0;
}

.homepage-buyer-board-memo-copy p {
  max-width: 760px;
  color: rgba(255, 253, 247, 0.72);
  font-size: 0.95rem;
  font-weight: 720;
  line-height: 1.48;
}

.homepage-buyer-board-memo-actions {
  min-width: 280px;
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px;
}

.homepage-buyer-board-memo-primary,
.homepage-buyer-board-memo-link {
  min-height: 36px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  border-radius: 999px;
  border: 1px solid rgba(255, 253, 247, 0.2);
  padding: 8px 12px;
  color: #fffdf7;
  background: rgba(255, 253, 247, 0.08);
  font-size: 0.78rem;
  font-weight: 900;
  line-height: 1;
  text-decoration: none;
  white-space: nowrap;
}

.homepage-buyer-board-memo-primary {
  color: #14221f;
  background: #b8efd4;
}

.homepage-buyer-board-memo-link.is-confirmed {
  color: #14221f;
  background: #b8efd4;
}

.homepage-buyer-board-memo-link.is-risk {
  border-color: rgba(255, 168, 188, 0.62);
  color: #ffdbe3;
}

.homepage-buyer-board-memo-primary:hover,
.homepage-buyer-board-memo-primary:focus-visible,
.homepage-buyer-board-memo-link:hover,
.homepage-buyer-board-memo-link:focus-visible,
.homepage-buyer-board-memo-questions a:hover,
.homepage-buyer-board-memo-questions a:focus-visible {
  outline: 2px solid rgba(184, 239, 212, 0.78);
  outline-offset: 2px;
  transform: translateY(-1px);
}

.homepage-buyer-board-memo-verdict {
  min-width: 0;
  display: grid;
  align-content: center;
  justify-items: center;
  gap: 3px;
  border: 1px solid rgba(255, 253, 247, 0.18);
  border-radius: 8px;
  padding: 12px;
  background: rgba(255, 253, 247, 0.08);
  text-align: center;
}

.homepage-buyer-board-memo-verdict strong {
  color: #fffdf7;
  font-size: clamp(2rem, 4vw, 3.5rem);
  line-height: 0.9;
}

.homepage-buyer-board-memo-verdict small {
  color: rgba(255, 253, 247, 0.66);
  font-size: 0.74rem;
  font-weight: 800;
}

.homepage-buyer-board-memo-metrics,
.homepage-buyer-board-memo-questions {
  grid-column: 1 / -1;
  min-width: 0;
  display: grid;
  gap: 8px;
}

.homepage-buyer-board-memo-metrics {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.homepage-buyer-board-memo-questions {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.homepage-buyer-board-memo-metrics article,
.homepage-buyer-board-memo-questions a {
  min-width: 0;
  display: grid;
  gap: 6px;
  align-content: start;
  border: 1px solid rgba(255, 253, 247, 0.16);
  border-left: 4px solid rgba(184, 239, 212, 0.72);
  border-radius: 8px;
  padding: 10px;
  color: #fffdf7;
  background: rgba(255, 253, 247, 0.07);
  text-decoration: none;
}

.homepage-buyer-board-memo-metrics article.attention,
.homepage-buyer-board-memo-questions a.attention {
  border-left-color: #f2b84b;
}

.homepage-buyer-board-memo-metrics article.blocked,
.homepage-buyer-board-memo-questions a.blocked {
  border-left-color: #b56576;
}

.homepage-buyer-board-memo-metrics strong,
.homepage-buyer-board-memo-questions strong {
  min-width: 0;
  color: #fffdf7;
  font-size: 0.93rem;
  line-height: 1.14;
  overflow-wrap: anywhere;
}

.homepage-buyer-board-memo-metrics p,
.homepage-buyer-board-memo-questions small {
  min-width: 0;
  color: rgba(255, 253, 247, 0.66);
  font-size: 0.73rem;
  font-weight: 740;
  line-height: 1.28;
  overflow-wrap: anywhere;
}

.homepage-proof-command-stack {
  display: grid;
  gap: 14px;
  padding: 18px;
  border: 1px solid #2b332d;
  border-radius: 8px;
  color: #fffdf7;
  background:
    linear-gradient(135deg, rgba(16, 19, 24, 0.98), rgba(20, 34, 31, 0.92)),
    #101318;
  box-shadow: var(--shadow);
}

.homepage-proof-command-stack-head {
  display: grid;
  grid-template-columns: minmax(0, 0.38fr) minmax(0, 0.72fr) minmax(220px, 0.46fr);
  gap: 14px;
  align-items: end;
}

.homepage-proof-command-stack-head span {
  color: rgba(184, 239, 212, 0.86);
  font-size: 0.72rem;
  font-weight: 950;
  line-height: 1.1;
  text-transform: uppercase;
}

.homepage-proof-command-stack-head strong {
  color: #fffdf7;
  font-size: clamp(1.3rem, 2.4vw, 2rem);
  line-height: 1.04;
  overflow-wrap: anywhere;
}

.homepage-proof-command-stack-head p {
  color: rgba(255, 253, 247, 0.68);
  font-size: 0.86rem;
  font-weight: 750;
  line-height: 1.42;
}

.homepage-proof-command-rail {
  display: grid;
