}

.homepage-proof-command-action span {
  color: rgba(184, 239, 212, 0.86);
  font-size: 0.66rem;
  font-weight: 950;
  line-height: 1.1;
  text-transform: uppercase;
}

.homepage-proof-command-action strong {
  min-width: 0;
  color: #fffdf7;
  font-size: 0.84rem;
  line-height: 1.12;
  overflow-wrap: anywhere;
