  color: rgba(255, 253, 247, 0.66);
  font-size: 0.7rem;
  font-weight: 760;
  line-height: 1.2;
  overflow-wrap: anywhere;
}

.homepage-proof-command-action.is-checking,
.homepage-proof-command-action.is-review,
.homepage-proof-command-action.is-attention {
  border-left-color: #f2b84b;
}

.homepage-proof-command-action.is-failed,
.homepage-proof-command-action.is-hold,
.homepage-proof-command-action.is-blocked {
  border-left-color: #b56576;
}

.homepage-proof-command-action.is-checked,
.homepage-proof-command-action.is-send,
.homepage-proof-command-action.is-ready {
  border-left-color: #77a06a;
}

.homepage-proof-command-action:disabled {
  cursor: wait;
  opacity: 0.78;
}

.homepage-proof-command-action:hover:not(:disabled),
.homepage-proof-command-action:focus-visible {
  outline: 2px solid rgba(184, 239, 212, 0.78);
  outline-offset: 2px;
  transform: translateY(-1px);
}

.homepage-proof-command-stack-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.12fr) minmax(300px, 0.72fr);
  gap: 12px;
  align-items: start;
}

.homepage-proof-command-stack .market-hero-output-strip,
.homepage-proof-command-stack .market-hero-acceptance-contract {
  width: 100%;
