.homepage-route-lock {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 148px minmax(210px, 0.26fr);
  gap: 12px;
  align-items: stretch;
  margin-top: 14px;
  padding: 14px;
  border: 1px solid #172126;
  border-radius: 8px;
  background:
    linear-gradient(120deg, rgba(23, 33, 38, 0.96), rgba(36, 87, 166, 0.9)),
    repeating-linear-gradient(90deg, rgba(255, 253, 249, 0.08) 0 1px, transparent 1px 54px);
  color: #fffdf7;
  box-shadow: var(--shadow);
}

.homepage-route-lock.is-ready {
  background:
    linear-gradient(120deg, rgba(13, 94, 81, 0.96), rgba(36, 87, 166, 0.9)),
    repeating-linear-gradient(90deg, rgba(255, 253, 249, 0.08) 0 1px, transparent 1px 54px);
}

.homepage-route-lock.is-attention {
  background:
    linear-gradient(120deg, rgba(89, 65, 18, 0.98), rgba(36, 87, 166, 0.9)),
    repeating-linear-gradient(90deg, rgba(255, 253, 249, 0.08) 0 1px, transparent 1px 54px);
}

.homepage-route-lock.is-blocked {
  background:
    linear-gradient(120deg, rgba(77, 28, 39, 0.98), rgba(23, 33, 38, 0.94)),
    repeating-linear-gradient(90deg, rgba(255, 253, 249, 0.08) 0 1px, transparent 1px 54px);
}

.homepage-route-main {
  min-width: 0;
}

.homepage-route-main .eyebrow {
  color: rgba(255, 253, 247, 0.76);
}

.homepage-route-main h2 {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 5px;
  font-family: "Avenir Next Condensed", "Hiragino Sans", sans-serif;
  font-size: clamp(1.55rem, 2.45vw, 2.65rem);
  line-height: 0.98;
  letter-spacing: 0;
}

.homepage-route-main p {
  max-width: 830px;
  margin-top: 8px;
  color: rgba(255, 253, 247, 0.8);
  line-height: 1.5;
}

.homepage-route-main strong {
  display: block;
  max-width: 880px;
  margin-top: 8px;
  color: #fffdf7;
  line-height: 1.35;
}

.homepage-route-score {
  min-width: 0;
  display: grid;
  place-items: center;
  align-content: center;
  gap: 4px;
  border: 1px solid rgba(255, 253, 247, 0.22);
  border-radius: 8px;
  background: rgba(255, 253, 247, 0.12);
  text-align: center;
}

.homepage-route-score span {
  max-width: 120px;
  color: rgba(255, 253, 247, 0.76);
  font-size: 0.72rem;
  font-weight: 950;
  text-transform: uppercase;
  overflow-wrap: anywhere;
}

.homepage-route-score strong {
  font-size: 3.4rem;
  line-height: 0.9;
}

.homepage-route-actions {
  min-width: 0;
  display: grid;
  align-content: center;
  gap: 8px;
}

.homepage-route-primary,
.homepage-route-actions .icon-link {
  min-height: 38px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border-radius: 999px;
  padding: 9px 12px;
  font-size: 0.84rem;
  font-weight: 950;
  line-height: 1.1;
  text-align: center;
  text-decoration: none;
}

.homepage-route-primary {
  color: #172126;
  border: 1px solid #fffdf7;
  background: #fffdf7;
}

.homepage-route-actions .icon-link {
  color: #fffdf7;
  border-color: rgba(255, 253, 247, 0.32);
  background: rgba(255, 253, 247, 0.1);
}

.homepage-route-steps {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 8px;
}

.homepage-route-steps a {
  min-width: 0;
  display: grid;
  gap: 5px;
  padding: 11px;
  border: 1px solid rgba(255, 253, 247, 0.2);
  border-top: 4px solid var(--green);
  border-radius: 8px;
  color: #fffdf7;
  background: rgba(255, 253, 247, 0.1);
  text-decoration: none;
}

.homepage-route-steps a.attention {
  border-top-color: var(--amber);
}

.homepage-route-steps a.blocked {
  border-top-color: var(--rose);
}

.homepage-route-steps a.current {
  border-color: rgba(255, 253, 247, 0.58);
  background: rgba(255, 253, 247, 0.18);
}

.homepage-route-steps span {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: rgba(255, 253, 247, 0.78);
  font-size: 0.68rem;
  font-weight: 950;
  text-transform: uppercase;
}

.homepage-route-steps b {
  width: 20px;
  height: 20px;
  display: inline-grid;
  place-items: center;
  border: 1px solid rgba(255, 253, 247, 0.26);
  border-radius: 999px;
  color: #172126;
  background: #fffdf7;
  font-size: 0.72rem;
  line-height: 1;
}

.homepage-route-steps strong {
  color: #fffdf7;
  font-size: 1rem;
  line-height: 1.1;
  overflow-wrap: anywhere;
}

.homepage-route-steps small {
  color: rgba(255, 253, 247, 0.72);
  font-size: 0.78rem;
  line-height: 1.3;
  overflow-wrap: anywhere;
}

.homepage-route-checks {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
}

.homepage-route-checks a {
  min-width: 0;
  display: grid;
  gap: 5px;
  padding: 10px;
  border: 1px solid rgba(255, 253, 247, 0.2);
  border-left: 4px solid var(--green);
  border-radius: 8px;
  color: #fffdf7;
  background: rgba(255, 253, 247, 0.1);
  text-decoration: none;
