.homepage-route-checks span {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: rgba(255, 253, 247, 0.76);
  font-size: 0.7rem;
  font-weight: 950;
  text-transform: uppercase;
}

.homepage-route-checks strong {
  color: #fffdf7;
  font-size: 1rem;
  line-height: 1.1;
  overflow-wrap: anywhere;
