  border: 1px solid rgba(23, 33, 38, 0.12);
  border-left: 5px solid var(--blue);
  border-radius: 8px;
  background: #fffdf7;
}

.global-launch-lift-actions li.now {
  border-left-color: var(--rose);
}

.global-launch-lift-actions li > div {
  min-width: 0;
}

.global-launch-lift-actions span {
  color: #172126;
}

.global-launch-lift-actions b {
  display: block;
  margin-top: 4px;
  color: #172126;
  font-size: 1.35rem;
  line-height: 1;
}

.global-launch-lift-actions strong,
.global-launch-lift-actions p,
.global-launch-lift-actions small {
  min-width: 0;
  overflow-wrap: anywhere;
}

.global-launch-lift-actions p,
.global-launch-lift-actions small {
  color: var(--muted);
  font-size: 0.82rem;
  font-weight: 760;
  line-height: 1.28;
}

.global-launch-lift-actions a {
  color: #2457a6;
}

.global-launch-dimensions {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.global-launch-dimensions article {
  min-height: 192px;
  display: grid;
  grid-template-rows: auto auto 1fr auto;
  gap: 8px;
  padding: 11px;
  border-top: 5px solid var(--amber);
}

.global-launch-dimensions article.pass {
  border-top-color: var(--teal);
  background: rgba(238, 250, 244, 0.9);
}

.global-launch-dimensions article.watch {
  border-top-color: var(--blue);
  background: rgba(244, 248, 255, 0.9);
}

.global-launch-dimensions article.block {
  border-top-color: var(--rose);
  background: rgba(255, 241, 242, 0.9);
}

.global-launch-dimensions article > div {
  min-width: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.global-launch-dimensions article > div span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
}

.global-launch-dimensions b {
  color: #172126;
  font-size: 1.55rem;
  line-height: 1;
}

.global-launch-dimensions p {
  color: var(--muted);
  font-size: 0.88rem;
  line-height: 1.34;
  overflow-wrap: anywhere;
}

.global-launch-proof-strip {
  display: grid;
  grid-template-columns: minmax(180px, 0.26fr) minmax(0, 1fr);
  gap: 10px;
  align-items: center;
  padding: 12px;
}

.global-launch-proof-strip > div:last-child {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}

.global-launch-proof-strip a.pass {
  color: #0b5f58;
  border-color: rgba(15, 118, 110, 0.22);
  background: #eefaf4;
}

.global-launch-proof-strip a.block {
  color: #8d2d42;
  border-color: rgba(177, 52, 79, 0.22);
  background: #fff1f2;
}

.global-launch-live-check {
  display: grid;
  gap: 10px;
  padding: 12px;
  border: 1px solid rgba(23, 33, 38, 0.14);
  border-radius: 8px;
  background: rgba(255, 253, 247, 0.9);
}

.global-launch-live-check.failed {
  border-color: rgba(177, 52, 79, 0.28);
  background: #fff1f2;
}

.global-launch-live-head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 140px;
  gap: 10px;
  align-items: stretch;
}

.global-launch-live-head > div {
  min-width: 0;
}

.global-launch-live-head > div:last-child {
  display: grid;
  align-content: center;
  justify-items: center;
  gap: 4px;
  padding: 10px;
  border: 1px solid rgba(23, 33, 38, 0.12);
  border-radius: 8px;
  color: #fffdf7;
  background: #172126;
}

.global-launch-live-head span,
.global-launch-live-results article > div span {
  color: var(--teal);
  font-size: 0.72rem;
  font-weight: 950;
  text-transform: uppercase;
}

.global-launch-live-head > div:last-child span {
  color: rgba(255, 253, 247, 0.72);
}

.global-launch-live-head strong {
  display: block;
  margin-top: 4px;
  line-height: 1.12;
  overflow-wrap: anywhere;
}

.global-launch-live-head > div:last-child strong {
  margin: 0;
  color: #fffdf7;
  font-size: 1.7rem;
}

.global-launch-live-head p {
  margin-top: 6px;
  color: var(--muted);
  font-size: 0.9rem;
  line-height: 1.35;
  overflow-wrap: anywhere;
}

.global-launch-live-results {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 8px;
}

.global-launch-live-results article {
  min-width: 0;
  min-height: 154px;
  display: grid;
  grid-template-rows: auto auto 1fr auto;
  gap: 7px;
  padding: 10px;
  border: 1px solid var(--line);
  border-top: 5px solid var(--amber);
  border-radius: 8px;
  background: #fffdf7;
}

.global-launch-live-results article.pass {
  border-top-color: var(--teal);
  background: #eefaf4;
}

.global-launch-live-results article.watch {
  border-top-color: var(--blue);
  background: #f1f6ff;
}

.global-launch-live-results article.block {
  border-top-color: var(--rose);
  background: #fff1f2;
}

.global-launch-live-results article > div {
  min-width: 0;
  display: flex;
  justify-content: space-between;
  gap: 8px;
}

.global-launch-live-results article > div span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
}

.global-launch-live-results b {
  color: #172126;
  font-size: 1.1rem;
}

.global-launch-live-results strong,
.global-launch-live-results p,
.global-launch-live-results small {
  overflow-wrap: anywhere;
}

.global-launch-live-results p {
  color: var(--muted);
  font-size: 0.86rem;
  line-height: 1.3;
}

.global-launch-live-results small {
  color: #40524b;
  font-size: 0.76rem;
  font-weight: 820;
  line-height: 1.24;
}

@media (max-width: 920px) {
  .global-launch-head,
  .global-launch-narrative,
  .global-launch-lift-plan,
  .global-launch-proof-strip,
  .global-launch-live-head {
    grid-template-columns: 1fr;
  }

  .global-launch-score {
    min-height: 126px;
  }

  .global-launch-metrics,
  .global-launch-lift-stats,
  .global-launch-dimensions,
  .global-launch-live-results {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .global-launch-lift-actions li {
    grid-template-columns: 72px minmax(0, 0.8fr) minmax(0, 1fr);
  }

  .global-launch-lift-actions p,
  .global-launch-lift-actions small,
  .global-launch-lift-actions a {
    grid-column: 2 / -1;
  }
}

@media (max-width: 640px) {
  .global-launch-audit {
    padding: 14px;
  }

  .global-launch-head h2 {
    align-items: flex-start;
    font-size: 1.24rem;
  }

  .global-launch-actions .icon-link,
  .global-launch-narrative a,
  .global-launch-lift-actions a,
  .global-launch-dimensions a,
  .global-launch-proof-strip a {
    width: 100%;
  }

  .global-launch-metrics,
  .global-launch-lift-stats,
  .global-launch-dimensions,
  .global-launch-live-results {
    grid-template-columns: 1fr;
  }

  .global-launch-score strong {
    font-size: 3rem;
  }

  .global-launch-narrative li {
    grid-template-columns: 1fr;
    align-items: start;
  }

  .global-launch-lift-actions li {
    grid-template-columns: 1fr;
    align-items: start;
  }

  .global-launch-narrative li span,
  .global-launch-lift-actions span {
    text-align: left;
  }

  .global-launch-lift-actions p,
  .global-launch-lift-actions small,
  .global-launch-lift-actions a {
    grid-column: auto;
  }
}

.buyer-pilot-fix-panel {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: minmax(0, 0.82fr) minmax(360px, 0.66fr) auto;
  gap: 12px;
  align-items: center;
  padding: 14px;
  border: 1px solid #e2bf74;
  border-radius: 8px;
  background: #fff7dd;
}

.buyer-pilot-fix-panel > div:first-child {
  min-width: 0;
}

.buyer-pilot-fix-panel span,
.buyer-pilot-levers label > span {
  color: #7b4d00;
  font-size: 0.72rem;
  font-weight: 950;
  text-transform: uppercase;
}

.buyer-pilot-fix-panel strong {
  display: block;
  margin-top: 4px;
  line-height: 1.14;
  overflow-wrap: anywhere;
}

.buyer-pilot-fix-panel p {
  margin-top: 6px;
  color: #665130;
  line-height: 1.4;
}

.buyer-pilot-levers {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.buyer-pilot-levers label {
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 5px;
  padding: 9px;
  border: 1px solid rgba(123, 77, 0, 0.2);
  border-radius: 8px;
  background: rgba(255, 253, 247, 0.86);
}

.buyer-pilot-levers label > span {
  grid-column: 1 / -1;
}

.buyer-pilot-levers input {
  width: 100%;
  min-width: 0;
  border: 0;
  border-bottom: 2px solid rgba(123, 77, 0, 0.25);
  border-radius: 0;
  padding: 4px 0;
  color: #172126;
  background: transparent;
  font-size: 1.2rem;
  font-weight: 950;
}

.buyer-pilot-levers input:focus {
  border-color: var(--blue);
  outline: 0;
}

.buyer-pilot-levers small {
  align-self: end;
  color: #7b4d00;
  font-weight: 900;
}

.buyer-pilot-fix-panel > a {
  min-height: 36px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  border: 1px solid rgba(123, 77, 0, 0.28);
  border-radius: 999px;
  padding: 8px 11px;
  color: #172126;
  background: #fffdf7;
  font-size: 0.82rem;
  font-weight: 900;
  text-decoration: none;
  white-space: nowrap;
}

.buyer-pilot-details {
  grid-column: 1 / -1;
  min-width: 0;
}

.buyer-pilot-details summary {
  min-height: 48px;
  display: grid;
  grid-template-columns: minmax(0, 0.42fr) minmax(0, 0.36fr) minmax(0, 1fr);
  gap: 10px;
  align-items: center;
  padding: 10px 12px;
  border: 1px solid var(--line);
  border-radius: 8px;
  color: #172126;
  background: #fffdf7;
