.buyer-pilot-details summary::-webkit-details-marker {
  display: none;
}

.buyer-pilot-details summary::after {
  content: "+";
  justify-self: end;
  width: 28px;
  height: 28px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(23, 33, 38, 0.14);
  border-radius: 999px;
  color: #fffdf7;
  background: var(--teal);
  font-weight: 950;
}

.buyer-pilot-details[open] summary::after {
  content: "-";
}

.buyer-pilot-details summary:focus-visible {
  outline: 3px solid rgba(15, 118, 110, 0.22);
  outline-offset: 2px;
}

.buyer-pilot-details summary span,
.buyer-pilot-details summary small {
  color: var(--teal);
  font-size: 0.72rem;
  font-weight: 950;
  text-transform: uppercase;
}

.buyer-pilot-details summary strong,
.buyer-pilot-details summary small {
  min-width: 0;
  overflow-wrap: anywhere;
}

.buyer-pilot-details summary strong {
  font-size: 1rem;
  line-height: 1.1;
}

.buyer-pilot-rail {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 8px;
  padding: 10px 0 0;
