}

.buyer-pilot-rail li {
  min-width: 0;
  min-height: 118px;
  display: grid;
  align-content: start;
  gap: 6px;
  padding: 12px;
  border: 1px solid var(--line);
  border-top: 5px solid var(--teal);
  border-radius: 8px;
  background: #fffdf7;
}

.buyer-pilot-rail li.ready {
  border-top-color: var(--teal);
  background: #edf8f1;
}

.buyer-pilot-rail li.attention {
  border-top-color: var(--amber);
  background: #fff7dd;
}

.buyer-pilot-rail li.blocked {
  border-top-color: var(--rose);
  background: #fff1f2;
}

.buyer-pilot-rail li.current {
  outline: 3px solid rgba(36, 87, 166, 0.2);
}

.buyer-pilot-rail a {
  text-decoration: none;
}

.buyer-pilot-rail small {
  color: var(--muted);
  line-height: 1.25;
  overflow-wrap: anywhere;
}

.template-picker {
  margin-top: 14px;
  border: 1px solid #242b27;
  border-radius: 8px;
  background: #fffdf7;
  box-shadow: var(--shadow);
  overflow: hidden;
}

.template-picker-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 16px;
  border-bottom: 1px solid #d7dfd9;
}

.template-picker-heading h2 {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 5px;
  font-size: 1.18rem;
}

.template-picker-heading > span {
  min-height: 30px;
  display: inline-flex;
  align-items: center;
  border: 1px solid #c9d4ce;
  border-radius: 999px;
  padding: 5px 10px;
  color: var(--muted);
  font-size: 0.78rem;
  font-weight: 900;
  white-space: nowrap;
  background: #edf3ef;
}

.template-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 1px;
  background: #d7dfd9;
}

.template-grid button {
  min-width: 0;
  min-height: 168px;
  display: grid;
  align-content: start;
  gap: 8px;
  padding: 15px;
  color: var(--ink);
  text-align: left;
  background: #fffdf7;
}

.template-grid button:hover,
.template-grid button:focus-visible {
  outline: 2px solid var(--teal);
  outline-offset: -4px;
  background: #edf3ef;
}

.template-grid button.active {
  color: #fffdf7;
  background: #102226;
}

.template-grid span {
  color: var(--teal);
  font-size: 0.73rem;
  font-weight: 950;
  text-transform: uppercase;
}

.template-grid button.active span,
.template-grid button.active p,
.template-grid button.active small {
  color: rgba(255, 253, 247, 0.76);
}

.template-grid strong {
  font-size: 1.18rem;
  line-height: 1.08;
}

.template-grid p {
  color: var(--muted);
  line-height: 1.5;
}

.template-grid small {
  align-self: end;
  border-top: 1px solid #d7dfd9;
  padding-top: 8px;
  color: #4b5c57;
  font-size: 0.78rem;
  font-weight: 850;
  line-height: 1.35;
  overflow-wrap: anywhere;
}

.workspace-status-bar {
  margin-top: 14px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  border: 1px solid #c9d4ce;
  border-radius: 8px;
  padding: 12px 14px;
  background:
    linear-gradient(90deg, rgba(255, 253, 247, 0.96), rgba(237, 243, 239, 0.96));
  box-shadow: 0 10px 24px rgba(23, 33, 38, 0.08);
}

.workspace-status-bar > div:first-child {
  min-width: 0;
}

.workspace-status-bar span {
  color: var(--teal);
  font-size: 0.73rem;
  font-weight: 950;
  text-transform: uppercase;
}

.workspace-status-bar strong {
  display: block;
  margin-top: 3px;
