  color: var(--muted);
  font-size: 0.78rem;
  font-weight: 850;
  line-height: 1.3;
}

.workspace-status-note.is-confirmed {
  color: var(--teal);
}

.workspace-status-note.is-risk {
  color: var(--rose);
}

.workspace-resume-packet {
