.workspace-resume-packet span {
  color: var(--teal);
  font-size: 0.68rem;
  font-weight: 950;
  line-height: 1.1;
  text-transform: uppercase;
}

.workspace-resume-packet strong {
  color: #172126;
  font-size: 0.86rem;
  line-height: 1.14;
  overflow-wrap: anywhere;
}

.workspace-resume-packet p {
