.workspace-resume-cover.watch strong {
  color: #8a5b11;
}

.workspace-resume-cover.blocked strong {
  color: #a3344c;
}

.workspace-resume-board.ready {
  border-top-color: rgba(15, 118, 110, 0.24);
}

.workspace-resume-board.watch {
  border-top-color: rgba(186, 126, 29, 0.24);
}

.workspace-resume-board.blocked {
  border-top-color: rgba(163, 52, 76, 0.24);
}

.workspace-resume-board.ready strong {
  color: #0f766e;
}

.workspace-resume-board.watch strong {
  color: #8a5b11;
}

.workspace-resume-board.blocked strong {
  color: #a3344c;
