.workflow-share-checks a:focus-visible,
.workflow-proof-verify:focus-visible,
.workflow-delivery-action:focus-visible,
.workflow-delivery-proof a:focus-visible,
.workflow-proof-slot input:focus-visible {
  outline: 2px solid #b8efd4;
  outline-offset: 2px;
}

.workflow-intake-preview {
  grid-template-columns: minmax(220px, 0.32fr) minmax(0, 1fr);
  align-items: stretch;
  padding: 10px;
}

.workflow-intake-preview > div {
  display: grid;
  align-content: center;
  gap: 6px;
}

.workflow-intake-preview pre {
  max-height: 170px;
  margin: 0;
  overflow: auto;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  color: #172126;
  border-radius: 8px;
  padding: 10px;
  background: rgba(255, 253, 247, 0.94);
}

.panel {
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--panel);
  box-shadow: 0 1px 0 rgba(23, 33, 38, 0.06);
  overflow: hidden;
}

.panel-heading,
.market-toolbar,
.agent-card-top,
.score-row,
.capability-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.panel-heading,
.market-toolbar {
  padding: 14px;
  border-bottom: 1px solid var(--line);
  background: color-mix(in srgb, var(--panel-strong) 72%, white);
}

.panel-heading h2,
.market-toolbar h2 {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.95rem;
  letter-spacing: 0;
}

.eyebrow {
  display: block;
  color: var(--teal);
  font-size: 0.72rem;
  font-weight: 900;
  text-transform: uppercase;
}

.chip {
  color: #21423d;
  background: #e8f3ee;
}

.judge-tools-heading p,
.judge-tools-link-panel p {
  margin: 14px;
  color: var(--muted);
  line-height: 1.55;
}

.judge-tools-heading a,
.judge-tools-link-panel a {
  margin: 0 14px 14px;
}

.brief-panel textarea {
  width: calc(100% - 28px);
  min-height: 270px;
  margin: 14px;
  padding: 13px;
  border: 1px solid var(--line);
  border-radius: 8px;
  color: var(--ink);
  background: #fffaf0;
  line-height: 1.55;
  resize: vertical;
}

.brief-panel textarea:focus,
.filter-block input:focus {
  outline: 3px solid rgba(15, 118, 110, 0.2);
  border-color: var(--teal);
}

.matched-terms,
.stage-tabs,
.requirement-stack,
.filter-block {
  margin: 0 14px 14px;
}

.matched-terms {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  min-height: 34px;
}

.matched-terms span {
  color: #5b4322;
  background: #fff0c8;
}

.filter-block {
  display: grid;
  gap: 8px;
}

.filter-block label {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--muted);
  font-size: 0.8rem;
  font-weight: 900;
}

.filter-block input {
  width: 100%;
  min-height: 42px;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 0 12px;
  background: #fffaf0;
}

.stage-tabs {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 7px;
}

.stage-tabs button {
  min-height: 36px;
  border: 1px solid var(--line);
  border-radius: 8px;
  color: var(--ink);
  background: #fbf5e9;
  font-size: 0.78rem;
  font-weight: 900;
}

.stage-tabs button.active {
  color: white;
  background: var(--teal);
  border-color: var(--teal);
}

.requirement-stack {
  display: grid;
  gap: 8px;
}

.requirement-stack div {
  min-height: 44px;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 12px;
  border-radius: 8px;
  background: #efe7d8;
  color: #26312d;
  font-weight: 850;
}

.agent-card-intake-body {
  display: grid;
  gap: 10px;
  padding: 12px;
}

.agent-card-discovery {
  display: grid;
  gap: 8px;
  padding: 10px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #f8efe1;
}

.agent-card-discovery label {
  color: var(--muted);
  font-size: 0.78rem;
  font-weight: 900;
}

.agent-card-discovery > div {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 8px;
}

.agent-card-discovery > div.agent-card-discovery-actions {
  grid-template-columns: minmax(0, 1fr) repeat(3, auto);
  align-items: center;
}

.agent-card-diligence-link {
  width: fit-content;
}

.agent-card-discovery input {
  width: 100%;
  min-height: 42px;
  padding: 0 11px;
  border: 1px solid var(--line);
  border-radius: 8px;
  color: var(--ink);
  background: #fffaf0;
}

.agent-card-intake textarea {
  width: 100%;
  min-height: 140px;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: 8px;
  color: var(--ink);
  background: #fffaf0;
  line-height: 1.45;
  resize: vertical;
}

.agent-card-discovery input:focus,
.agent-card-intake textarea:focus {
  outline: 3px solid rgba(15, 118, 110, 0.2);
  border-color: var(--teal);
}

.agent-card-intake-note {
  margin: 0;
  color: #7a4d13;
  font-size: 0.82rem;
  font-weight: 800;
}

.agent-card-intake-result {
  display: grid;
  gap: 5px;
  padding: 10px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #fff9ee;
}

.agent-card-intake-result.accepted {
  border-color: rgba(15, 118, 110, 0.3);
  background: #edf8f2;
}

.agent-card-intake-result.rejected {
  border-color: rgba(173, 83, 69, 0.35);
  background: #fff0ec;
}

.agent-card-intake-result strong {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 0.88rem;
}

.agent-card-intake-result p,
.agent-card-intake-result small {
  margin: 0;
  color: var(--muted);
  font-size: 0.78rem;
  line-height: 1.4;
}

.agent-trust-passport {
  display: grid;
  gap: 10px;
  padding: 11px;
  border: 1px solid rgba(32, 91, 82, 0.18);
  border-radius: 8px;
  background: #f3f9f4;
}

.agent-trust-passport.medium {
  border-color: rgba(153, 113, 38, 0.25);
  background: #fff8e8;
}

.agent-trust-passport.high {
  border-color: rgba(148, 66, 48, 0.25);
  background: #fff1ed;
}

.agent-trust-passport > div:first-child,
.agent-trust-score,
.agent-trial-task {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.agent-trust-passport > div:first-child strong,
.agent-trial-task {
  display: flex;
  align-items: center;
  gap: 7px;
}

.agent-trust-passport > div:first-child strong {
  font-size: 0.9rem;
  line-height: 1.25;
}

.agent-trust-score {
  padding: 9px 10px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.66);
}

.agent-trust-score span,
.agent-trust-score small {
  color: var(--muted);
  font-size: 0.76rem;
  font-weight: 900;
  text-transform: uppercase;
}

.agent-trust-score strong {
  font-size: 1.6rem;
}

.agent-trust-checks {
  display: grid;
  gap: 7px;
}

.agent-trust-checks article {
  display: grid;
  grid-template-columns: 48px minmax(0, 0.68fr) minmax(0, 1fr);
  gap: 8px;
  align-items: center;
  padding: 8px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.72);
}

.agent-trust-checks article span {
  color: #1d6a5e;
  font-size: 0.68rem;
  font-weight: 950;
  text-transform: uppercase;
}

.agent-trust-checks article.watch span {
  color: #92610f;
}

.agent-trust-checks article.fail span {
  color: #994332;
}

.agent-trust-checks article strong,
.agent-trust-checks article small {
  min-width: 0;
  overflow-wrap: anywhere;
}

.agent-trust-checks article strong {
  font-size: 0.78rem;
}

.agent-trust-checks article small,
.agent-trial-task span,
.agent-trial-task p {
  margin: 0;
  color: var(--muted);
  font-size: 0.74rem;
  line-height: 1.35;
}

.agent-trial-task {
  justify-content: flex-start;
  padding: 9px;
  border: 1px solid rgba(15, 118, 110, 0.18);
  border-radius: 8px;
  background: #eef7f4;
}

.agent-trial-task div {
  min-width: 0;
}

.agent-trial-task span {
  display: block;
  font-weight: 950;
}

.agent-trial-receipt {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  align-items: center;
  padding: 9px;
  border: 1px dashed rgba(15, 118, 110, 0.28);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.62);
}

.agent-trial-receipt div {
  grid-column: 1 / -1;
  min-width: 0;
}

.agent-trial-receipt .icon-link {
  width: 100%;
  justify-content: center;
}

.agent-trial-receipt span,
.agent-trial-receipt small {
  display: block;
  color: var(--muted);
  font-size: 0.72rem;
  font-weight: 900;
  text-transform: uppercase;
}

.agent-trial-receipt strong {
  display: block;
  margin: 2px 0;
  font-size: 0.78rem;
  overflow-wrap: anywhere;
}

.agent-trial-receipt .icon-link.is-confirmed,
.agent-trial-verification .icon-link.is-confirmed {
  color: #126154;
  background: #daf3e9;
}

.agent-trial-receipt .icon-link.is-risk,
.agent-trial-verification .icon-link.is-risk {
  color: #963f2d;
  background: #ffebe5;
}

.agent-trial-verifier {
  display: grid;
  gap: 9px;
  padding: 10px;
  border: 1px solid rgba(23, 33, 38, 0.12);
  border-radius: 8px;
  background: rgba(255, 253, 247, 0.66);
}

.agent-trial-verifier-heading,
.agent-trial-verification-score {
  display: grid;
  gap: 10px;
  align-items: start;
}

.agent-trial-verifier-heading {
  grid-template-columns: 1fr;
}

.agent-trial-verifier-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-start;
  gap: 8px;
}

.agent-trial-verifier-actions .icon-link {
  flex: 1 1 160px;
  justify-content: center;
}

.agent-trial-verification-score {
  grid-template-columns: minmax(0, 1fr) auto auto;
}

.agent-trial-verifier-heading strong {
  display: block;
  margin-top: 2px;
  font-size: 0.86rem;
}

.agent-trial-verifier textarea {
  min-height: 118px;
  background: #fffdf7;
}

.agent-trial-artifact-gate {
  min-width: 0;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 6px;
  align-items: start;
  color: #126154;
}

.agent-trial-artifact-gate small {
  min-width: 0;
  color: #315c53;
  font-size: 0.72rem;
  font-weight: 850;
  line-height: 1.32;
  overflow-wrap: anywhere;
}

.agent-trial-verification {
  display: grid;
  gap: 9px;
  padding: 10px;
  border: 1px solid rgba(15, 118, 110, 0.18);
  border-radius: 8px;
  background: #edf8f2;
}

.agent-trial-verification.needs-evidence {
  border-color: rgba(153, 113, 38, 0.22);
  background: #fff8e8;
}

.agent-trial-verification.failed {
  border-color: rgba(148, 66, 48, 0.24);
  background: #fff1ed;
}

.agent-trial-verification-score > div {
  min-width: 0;
}

.agent-trial-verification-score span,
.agent-trial-verification-score small,
.agent-trial-verification-missing {
  display: block;
  color: var(--muted);
  font-size: 0.72rem;
  font-weight: 900;
  line-height: 1.35;
  text-transform: uppercase;
}

.agent-trial-verification-score strong {
  display: inline-block;
  margin: 1px 8px 0 0;
  font-size: 1.5rem;
}

.agent-trial-verification p {
  margin: 0;
  color: #31423c;
  font-size: 0.78rem;
  font-weight: 800;
  line-height: 1.38;
}

.agent-trial-verification-checks {
  display: grid;
  gap: 6px;
}

.agent-trial-verification-checks article {
  display: grid;
  grid-template-columns: 48px minmax(0, 0.62fr) minmax(0, 1fr);
  gap: 8px;
  align-items: center;
  padding: 7px 8px;
  border: 1px solid rgba(23, 33, 38, 0.1);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.7);
}

.agent-trial-verification-checks article span {
  color: #1d6a5e;
  font-size: 0.68rem;
  font-weight: 950;
  text-transform: uppercase;
}

.agent-trial-verification-checks article.watch span {
  color: #92610f;
}

.agent-trial-verification-checks article.fail span {
  color: #994332;
}

.agent-trial-verification-checks article strong,
.agent-trial-verification-checks article small {
  min-width: 0;
  overflow-wrap: anywhere;
}

.agent-trial-verification-checks article strong {
  font-size: 0.76rem;
}

.agent-trial-verification-checks article small {
  color: var(--muted);
  font-size: 0.72rem;
  line-height: 1.35;
}

.agent-trial-handoff {
  display: grid;
  gap: 9px;
  padding: 10px;
  border: 1px solid rgba(15, 118, 110, 0.18);
  border-radius: 8px;
  background: #eef8f5;
}

.agent-trial-handoff.needs-evidence {
  border-color: rgba(153, 113, 38, 0.22);
  background: #fff8e8;
}

.agent-trial-handoff.blocked {
  border-color: rgba(148, 66, 48, 0.24);
  background: #fff1ed;
}

.agent-trial-handoff-head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 10px;
  align-items: start;
}

.agent-trial-handoff-head > div {
  min-width: 0;
}

.agent-trial-handoff-head span,
.agent-trial-handoff-head small,
.agent-trial-handoff-proof {
  display: block;
  color: var(--muted);
  font-size: 0.72rem;
  font-weight: 900;
  line-height: 1.35;
  text-transform: uppercase;
}

.agent-trial-handoff-head strong {
  display: inline-block;
  margin: 1px 8px 0 0;
  font-size: 1.5rem;
}

.agent-trial-handoff-proof {
  padding: 8px 9px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.74);
}

.agent-trial-handoff-proof.is-confirmed {
  color: #126154;
  background: #daf3e9;
}

.agent-trial-handoff p {
  margin: 0;
  color: #31423c;
  font-size: 0.78rem;
  font-weight: 800;
  line-height: 1.38;
}

.agent-trial-handoff-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}

.agent-trial-handoff-actions .icon-link {
  min-height: 34px;
  background: rgba(255, 255, 255, 0.74);
}

.agent-trial-handoff-actions .icon-link.is-confirmed {
  color: #126154;
  background: #daf3e9;
}

.agent-trial-handoff-actions .icon-link.is-risk {
  color: #7b2d24;
  background: #ffe0db;
}

.agent-trial-handoff-links {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 7px;
}

.agent-trial-handoff-links a {
  min-width: 0;
  min-height: 38px;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 8px 9px;
  border: 1px solid rgba(15, 118, 110, 0.16);
  border-radius: 8px;
  color: #143833;
  background: rgba(255, 255, 255, 0.72);
  font-size: 0.74rem;
  font-weight: 900;
  text-decoration: none;
}

.agent-trial-handoff-links a span {
  min-width: 0;
  overflow-wrap: anywhere;
}

.imported-agent-list {
  display: grid;
  gap: 8px;
}

.imported-agent-list article {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 10px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #f7efe2;
}

.imported-agent-list strong,
.imported-agent-list span {
  display: block;
}

.imported-agent-list strong {
  font-size: 0.88rem;
}

.imported-agent-list span {
  color: var(--muted);
  font-size: 0.76rem;
  font-weight: 800;
}

.imported-agent-list button {
  min-height: 32px;
  border: 1px solid rgba(116, 55, 44, 0.22);
  border-radius: 8px;
  color: #74372c;
  background: #fff5ef;
  font-size: 0.74rem;
  font-weight: 900;
}

.market-panel {
  min-width: 0;
}

.toolbar-badges {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: flex-end;
}

.toolbar-badges span {
  color: #173d5f;
  background: #e8f0f8;
}

.agent-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  padding: 12px;
}

.agent-card {
  position: relative;
  display: grid;
  gap: 12px;
  min-height: 428px;
  padding: 14px;
  border: 1px solid color-mix(in srgb, var(--agent) 28%, var(--line));
  border-radius: 8px;
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--agent-accent) 16%, white), white 48%),
    var(--panel);
}

.agent-card.is-selected {
  border-color: var(--agent);
  box-shadow: inset 0 0 0 2px var(--agent), 0 14px 24px rgba(23, 33, 38, 0.12);
}

.agent-avatar {
  width: 44px;
  height: 44px;
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  border-radius: 8px;
  color: white;
  background: var(--agent);
}

.agent-card-top {
  align-items: flex-start;
}

.agent-card-top > div:nth-child(2) {
  min-width: 0;
  flex: 1;
}

.agent-handle {
  display: block;
  color: var(--muted);
  font-size: 0.78rem;
  font-weight: 850;
}

.agent-card h3 {
  margin-top: 3px;
  font-size: 1.24rem;
  letter-spacing: 0;
  overflow-wrap: anywhere;
}

.rarity {
  border-color: color-mix(in srgb, var(--agent) 38%, var(--line));
  color: var(--agent);
  background: color-mix(in srgb, var(--agent-accent) 25%, white);
  text-transform: uppercase;
}

.rarity.legendary {
  color: #5d4214;
  background: #ffe8a3;
}

.rarity.epic {
  color: #5a325c;
  background: #f4ddf5;
}

.rarity.rare {
  color: #174f70;
  background: #dff1fb;
}

.agent-headline {
  min-height: 48px;
  color: #3b3d39;
  line-height: 1.5;
}

.agent-metrics,
.skill-row {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}

.agent-metrics span {
  color: #26312d;
  background: #f4eee4;
}

.capability-stack {
  display: grid;
  gap: 8px;
}

.capability-row,
.score-row {
  font-size: 0.78rem;
  font-weight: 850;
}

.capability-row span,
.score-row span {
  color: var(--muted);
}

.meter,
.score-track {
  position: relative;
  height: 9px;
  border-radius: 999px;
  background: #e4dccf;
  overflow: hidden;
}

.meter span,
.score-track span {
  position: absolute;
  inset: 0 auto 0 0;
  border-radius: inherit;
}

.meter[data-tone="elite"] span,
.score-track .after {
  background: linear-gradient(90deg, var(--teal), #77a06a);
}

.meter[data-tone="solid"] span {
  background: linear-gradient(90deg, var(--blue), #86bbd8);
}

.meter[data-tone="quiet"] span {
  background: linear-gradient(90deg, var(--amber), #e07a5f);
}

.skill-row span {
  min-height: 26px;
  color: #3f3528;
  background: #fff5dd;
  font-size: 0.72rem;
}

.agent-buyer-proof {
  display: grid;
  gap: 7px;
  min-height: 104px;
  padding-top: 11px;
  border-top: 1px solid color-mix(in srgb, var(--agent) 24%, var(--line));
}

.agent-buyer-proof > div {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.agent-buyer-proof span {
  color: #485651;
  font-size: 0.72rem;
  font-weight: 900;
  text-transform: uppercase;
}

.agent-buyer-proof strong {
  color: #26312d;
  font-size: 0.9rem;
  font-weight: 950;
  text-align: right;
}

.agent-buyer-proof p {
  margin: 0;
  color: #404941;
  font-size: 0.78rem;
  line-height: 1.45;
}

.agent-buyer-proof a {
  width: fit-content;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: var(--agent);
  font-size: 0.76rem;
  font-weight: 900;
  text-decoration: none;
}

.agent-buyer-proof.ready strong,
.agent-buyer-proof.ready a {
  color: #0f766e;
