.ops-grid {
  display: grid;
  grid-template-columns: minmax(320px, 0.95fr) minmax(360px, 1fr) minmax(360px, 1fr);
  gap: 1px;
  background: var(--line);
}

.ops-grid > section {
  display: grid;
  align-content: start;
  gap: 10px;
  padding: 14px;
  background: #fffdf9;
}

.ops-grid h3 {
  display: flex;
  align-items: center;
  gap: 7px;
  color: var(--muted);
  font-size: 0.78rem;
  text-transform: uppercase;
}

.ops-decision,
.ops-steps article,
.ops-next-agent {
  display: grid;
  gap: 7px;
  padding: 11px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #f6f8f4;
}

.ops-decision span {
  color: var(--teal);
  font-weight: 950;
}

.ops-decision p,
.ops-steps p,
.ops-next-agent p,
.ops-empty p {
  color: #434a46;
  line-height: 1.45;
}

.ops-decision small,
.ops-steps small {
  color: var(--muted);
  line-height: 1.35;
}

.ops-steps {
  display: grid;
  gap: 8px;
}

.ops-steps span,
.ops-next-agent span {
  width: fit-content;
  min-height: 25px;
  display: inline-flex;
  align-items: center;
  border-radius: 999px;
  padding: 4px 9px;
  color: #14342f;
  background: #dcefe4;
  font-size: 0.72rem;
  font-weight: 950;
  text-transform: uppercase;
}

.ops-next-agent {
  margin-top: 10px;
  border-color: #f0c46e;
  background: #fff8e6;
}

.ops-empty {
  min-height: 210px;
  display: grid;
  place-items: center;
  align-content: center;
  gap: 10px;
  padding: 22px;
  text-align: center;
}

.gemini-panel {
  grid-column: span 2;
}

.analysis,
.empty-analysis,
.mcp-table,
.plan-panel ol {
  padding: 14px;
}

.analysis {
  display: grid;
  gap: 12px;
}

.analysis > strong {
  font-size: 1.15rem;
}

.analysis p,
.empty-analysis p,
.plan-panel li,
.analysis li {
  color: #46443e;
  line-height: 1.55;
}

.analysis-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.analysis h3 {
  margin-bottom: 7px;
  font-size: 0.86rem;
}

.analysis ul {
  margin: 0;
  padding-left: 18px;
}

pre {
  max-width: 100%;
  overflow: auto;
  margin: 0;
  border-radius: 8px;
  padding: 12px;
  color: #f6f0df;
  background: #172126;
  font-size: 0.78rem;
  line-height: 1.5;
  white-space: pre-wrap;
}

.empty-analysis {
  min-height: 260px;
  display: grid;
  place-items: center;
  align-content: center;
  gap: 10px;
  text-align: center;
}

.empty-analysis p {
  max-width: 520px;
}

.error-text {
  margin: 14px;
  color: #9d2d2d;
  font-weight: 850;
}

.mcp-table {
  display: grid;
  gap: 10px;
}

.mcp-table > div {
  display: grid;
  gap: 6px;
  padding: 11px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #fff9ee;
}

.mcp-table span,
.mcp-table small {
  color: var(--muted);
}

.plan-panel ol {
  margin: 0;
  display: grid;
  gap: 10px;
  padding-left: 34px;
}

.agent-card-json {
  max-height: 560px;
}

.agent-card-json pre {
  min-height: 492px;
  border-radius: 0;
}

