/* =====================================================================
   Focus & readability layer — declutter the long homepage stack.
   Goal: consistent vertical rhythm, calmer reading width, stronger hero,
   and a clear disclosure for the deep workspace tools.
   ===================================================================== */

/* One consistent gap between every top-level section, regardless of each
   panel's own ad-hoc margins. Only block-direction margins are reset so
   horizontal centering (margin: 0 auto) is preserved. */
.app-shell {
  display: flex;
  flex-direction: column;
  gap: clamp(28px, 3.6vw, 56px);
}

.app-shell > * {
  margin-top: 0 !important;
  margin-bottom: 0 !important;
}

/* Workspace tools disclosure (collapses the deep buyer/pilot/sponsor tail) */
.workspace-tools-divider {
  display: flex;
}

.workspace-tools-toggle {
  width: 100%;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-areas:
    "eyebrow badge"
    "title   badge"
    "desc    badge";
  align-items: center;
  column-gap: 18px;
  row-gap: 3px;
  text-align: left;
  padding: 18px 22px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background:
    linear-gradient(135deg, rgba(15, 118, 110, 0.07), rgba(36, 87, 166, 0.05)),
    var(--panel);
  box-shadow: var(--shadow);
  transition:
    transform 160ms ease,
    border-color 160ms ease,
    box-shadow 160ms ease;
}

.workspace-tools-toggle:hover,
.workspace-tools-toggle:focus-visible {
  transform: translateY(-1px);
  border-color: var(--teal);
  outline: none;
}

.workspace-tools-toggle:focus-visible {
  outline: 2px solid var(--teal);
  outline-offset: 3px;
}

.workspace-tools-toggle span {
  grid-area: eyebrow;
  color: var(--teal);
  font-size: 0.7rem;
  font-weight: 900;
  letter-spacing: 0.09em;
  text-transform: uppercase;
}

.workspace-tools-toggle strong {
  grid-area: title;
  color: var(--ink);
  font-size: 1.16rem;
  line-height: 1.22;
}

.workspace-tools-toggle small {
  grid-area: desc;
  color: var(--muted);
  font-size: 0.86rem;
  line-height: 1.45;
}

.workspace-tools-toggle em {
  grid-area: badge;
  align-self: center;
  justify-self: end;
  min-height: 42px;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 0 18px;
  border-radius: 999px;
  background: var(--ink);
  color: var(--paper);
  font-style: normal;
  font-weight: 900;
  font-size: 0.85rem;
  white-space: nowrap;
}

.workspace-tools-toggle.is-open em {
  background: var(--teal);
}

.workspace-tools-toggle.proof-detail-toggle {
  background:
    linear-gradient(135deg, rgba(36, 87, 166, 0.08), rgba(181, 101, 118, 0.05)),
    var(--panel);
}

.workspace-tools-toggle.proof-detail-toggle span {
  color: var(--blue);
}

.workspace-tools-toggle.proof-detail-toggle:hover,
.workspace-tools-toggle.proof-detail-toggle:focus-visible {
  border-color: var(--blue);
}

.workspace-tools-toggle.proof-detail-toggle.is-open em {
  background: var(--blue);
}

/* Hero console "judgment + artifacts" disclosure — keep the moved detail
   blocks spaced like the console grid when the drawer is open. */
.hero-workflow-brief-details-body {
  display: grid;
  gap: 9px;
  margin-top: 9px;
}

@media (max-width: 560px) {
  .workspace-tools-toggle {
    grid-template-columns: minmax(0, 1fr);
    grid-template-areas:
      "eyebrow"
      "title"
      "desc"
      "badge";
    row-gap: 8px;
  }

  .workspace-tools-toggle em {
    justify-self: start;
  }
}

/* Desktop-only: comfortable reading width + a hero with more presence.
   Scoped above the 920px breakpoint so the existing mobile tuning is kept. */
@media (min-width: 921px) {
  .app-shell {
    width: min(1440px, calc(100vw - 32px));
