    font-size: clamp(3.4rem, 4.8vw, 4.7rem);
    line-height: 0.94;
    letter-spacing: -0.01em;
    text-shadow: 0 2px 22px rgba(0, 0, 0, 0.34);
  }

  .market-identity p {
    font-size: 1.12rem;
  }

  .market-hero-primary {
    min-height: 48px;
    padding: 12px 24px;
    font-size: 1rem;
  }

